package pe.edu.upc.center.creditotiendas.billing.domain.model.aggregates;

import lombok.Getter;
import lombok.Setter;
import pe.edu.upc.center.creditotiendas.billing.domain.model.valueobjects.InstallmentStatuses;
import pe.edu.upc.center.creditotiendas.shared.domain.model.aggregates.AbstractDomainAggregateRoot;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * One installment of a credit sale (model: Cuota_Cronograma, US-07).
 *
 * <p>Generated by Billing when it receives {@code CreditSaleRegisteredEvent} from Credit; one row per
 * {@code ScheduledInstallment} of the sale's payment plan. The plan comes from the sale's rate snapshot, so
 * editing the profile never changes a persisted installment.</p>
 */
@Getter
public class Installment extends AbstractDomainAggregateRoot<Installment> {

    @Setter private Long id;
    @Setter private Long creditSaleId;
    /** Denormalized from Credit so Billing can query by profile without crossing contexts in SQL. */
    @Setter private Long creditProfileId;
    @Setter private int number;
    @Setter private LocalDate dueDate;
    @Setter private BigDecimal capital;
    @Setter private BigDecimal interest;
    @Setter private BigDecimal fixedInstallment;
    @Setter private BigDecimal remainingBalance;
    @Setter private InstallmentStatuses status;
    @Setter private LocalDate paymentDate;

    public Installment() {
        this.status = InstallmentStatuses.PENDING;
    }

    public Installment(Long creditSaleId, Long creditProfileId, int number, LocalDate dueDate, BigDecimal capital,
                       BigDecimal interest, BigDecimal fixedInstallment, BigDecimal remainingBalance) {
        this();
        this.creditSaleId = creditSaleId;
        this.creditProfileId = creditProfileId;
        this.number = number;
        this.dueDate = dueDate;
        this.capital = capital;
        this.interest = interest;
        this.fixedInstallment = fixedInstallment;
        this.remainingBalance = remainingBalance;
    }

    public boolean isOverdueAt(LocalDate asOf) {
        return !status.isPaid() && dueDate.isBefore(asOf);
    }

    /**
     * Flips a {@code PENDING} installment to {@code OVERDUE} when the due date has passed. Idempotent.
     */
    public Installment markOverdueIfLate(LocalDate asOf) {
        if (status == InstallmentStatuses.PENDING && dueDate.isBefore(asOf))
            this.status = InstallmentStatuses.OVERDUE;
        return this;
    }

    /**
     * Marks the installment as paid on {@code paymentDate}. The resulting status is {@code PAID_ON_TIME} when
     * the payment is on or before the due date, {@code PAID_LATE} otherwise.
     *
     * @throws IllegalStateException if the installment was already paid
     */
    public Installment markPaid(LocalDate paymentDate) {
        if (status.isPaid())
            throw new IllegalStateException("[Installment] installment %d was already paid".formatted(number));
        this.paymentDate = paymentDate;
        this.status = paymentDate.isAfter(dueDate) ? InstallmentStatuses.PAID_LATE : InstallmentStatuses.PAID_ON_TIME;
        return this;
    }
}
